// Inspect the exact properties of the given Button, Text Field, Status Bar, Home Indicator, Logo, Avatar, and Story_Text
function dump(node, depth, out) {
  if (depth > 3) return;
  const rec = {
    id: node.id, name: node.name, type: node.type,
    w: node.width, h: node.height,
  };
  if ('fills' in node) rec.fills = node.fills;
  if ('strokes' in node) rec.strokes = node.strokes;
  if ('strokeWeight' in node) rec.strokeWeight = node.strokeWeight;
  if ('cornerRadius' in node) rec.cornerRadius = node.cornerRadius;
  if ('layoutMode' in node) { rec.layoutMode = node.layoutMode; rec.primaryAxisAlignItems = node.primaryAxisAlignItems; rec.counterAxisAlignItems = node.counterAxisAlignItems; rec.paddingLeft = node.paddingLeft; rec.paddingRight = node.paddingRight; rec.paddingTop = node.paddingTop; rec.paddingBottom = node.paddingBottom; rec.itemSpacing = node.itemSpacing; }
  if (node.type === 'TEXT') { rec.characters = node.characters; rec.fontName = node.fontName; rec.fontSize = node.fontSize; rec.lineHeight = node.lineHeight; rec.textAlignHorizontal = node.textAlignHorizontal; rec.textAlignVertical = node.textAlignVertical; rec.textAutoResize = node.textAutoResize; }
  out.push(rec);
  if ('children' in node) for (const c of node.children) dump(c, depth+1, out);
}
