function nav(node, target, opts={}){
  if(!node) return 'MISS';
  const action = {
    type:'NODE', destinationId: target.id, navigation:'NAVIGATE',
    transition: opts.noAnim? null : {type: opts.smart? 'SMART_ANIMATE':'DISSOLVE', easing:{type:'EASE_OUT'}, duration: opts.smart?0.35:0.25},
    preserveScrollPosition:false, resetVideoPosition:false, resetScrollPosition:false
  };
  node.reactions = [{ trigger:{type:'ON_CLICK'}, actions:[action] }];
  return node.name;
}
