// Final reaction audit across all 12 frames: list source -> destination
const ws = await figma.getNodeByIdAsync('5:2');
const NAMES = ['01_Login','02_Home_Chats','03_Home_Images','04_Home_Exports','05_Chat_New','06_Chat_Conversation','07_Export_PDF_Sheet','08_Profile_Settings','09_Account_Actions_Sheet','10_Theme_Sheet','11_Cloud_Space','12_Clear_Cache_Dialog'];
const nameOf = async id => { const n = await figma.getNodeByIdAsync(id); return n? n.name : id; };
const out = {};
for(const nm of NAMES){
  const f = ws.children.find(x=>x.name===nm);
  const rows = [];
  const walk = async n => {
    if(n.reactions && n.reactions.length){
      const a = n.reactions[0].actions[0];
      rows.push(n.name + ' -> ' + await nameOf(a.destinationId));
    }
    if('children' in n) for(const c of n.children) await walk(c);
  };
  await walk(f);
  out[nm] = rows;
}
return out;
